package piglatin

import "strings"

// Sentence translates a full sentence from English to Pig Latin,
// converting each word and joining them with single spaces.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

// word translates a single word to Pig Latin.
func word(w string) string {
	if w == "" {
		return w
	}
	// Rule 1: begins with a vowel, or with "xr" or "yt".
	if isVowel(w[0]) || startsWith(w, "xr") || startsWith(w, "yt") {
		return w + "ay"
	}
	// Find where the leading consonant cluster ends.
	i := 0
	for i < len(w) {
		c := w[i]
		if isVowel(c) {
			break
		}
		// Rule 3: "qu" is treated as part of the consonant cluster.
		if c == 'q' && i+1 < len(w) && w[i+1] == 'u' {
			i += 2
			continue
		}
		// Rule 4: "y" acts as a vowel once it follows a consonant.
		if c == 'y' && i > 0 {
			break
		}
		i++
	}
	// Rule 2 (and the cluster above): move the leading consonants to the end.
	return w[i:] + w[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func startsWith(w, prefix string) bool {
	return len(w) >= len(prefix) && w[:len(prefix)] == prefix
}
